import java.util.ArrayDeque;
import java.util.Deque;

public class GridTour {
    static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};   // up, down, left, right

    static boolean inBounds(char[][] g, int r, int c) {
        return r >= 0 && r < g.length && c >= 0 && c < g[0].length;
    }

    // Shortest number of steps from S to E, moving through '.' cells
    static int shortestPath(char[][] g, int sr, int sc) {
        int[][] dist = new int[g.length][g[0].length];
        for (int[] row : dist) java.util.Arrays.fill(row, -1);
        Deque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{sr, sc});
        dist[sr][sc] = 0;
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            for (int[] d : DIRS) {
                int r = cell[0] + d[0], c = cell[1] + d[1];
                if (!inBounds(g, r, c) || g[r][c] == '#' || dist[r][c] != -1) continue;
                dist[r][c] = dist[cell[0]][cell[1]] + 1;
                if (g[r][c] == 'E') return dist[r][c];
                queue.add(new int[]{r, c});
            }
        }
        return -1;
    }

    // Count islands of '1' by sinking each one we find (in-place marking)
    static int countIslands(char[][] g) {
        int islands = 0;
        for (int r = 0; r < g.length; r++)
            for (int c = 0; c < g[0].length; c++)
                if (g[r][c] == '1') { islands++; sink(g, r, c); }
        return islands;
    }

    static void sink(char[][] g, int r, int c) {
        if (!inBounds(g, r, c) || g[r][c] != '1') return;
        g[r][c] = '0';
        for (int[] d : DIRS) sink(g, r + d[0], c + d[1]);
    }

    public static void main(String[] args) {
        String[] maze = {
            "S.#.....",
            ".##.###.",
            "....#...",
            ".##...#E",
        };
        char[][] g = new char[maze.length][];
        for (int i = 0; i < maze.length; i++) { g[i] = maze[i].toCharArray(); System.out.println(maze[i]); }
        System.out.println("shortest path S -> E: " + shortestPath(g, 0, 0) + " steps");

        String[] map = {"11000", "11010", "00011", "10001"};
        char[][] land = new char[map.length][];
        for (int i = 0; i < map.length; i++) land[i] = map[i].toCharArray();
        System.out.println("islands in " + String.join("/", map) + ": " + countIslands(land));
    }
}

