DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right


def in_bounds(g, r, c):
    return 0 <= r < len(g) and 0 <= c < len(g[0])


def shortest_path(g, sr, sc):
    """Shortest number of steps from S to E, moving through '.' cells."""
    dist = [[-1] * len(g[0]) for _ in g]
    queue = deque([(sr, sc)])
    dist[sr][sc] = 0
    while queue:
        cr, cc = queue.popleft()
        for dr, dc in DIRS:
            r, c = cr + dr, cc + dc
            if not in_bounds(g, r, c) or g[r][c] == "#" or dist[r][c] != -1:
                continue
            dist[r][c] = dist[cr][cc] + 1
            if g[r][c] == "E":
                return dist[r][c]
            queue.append((r, c))
    return -1


def count_islands(g):
    """Count islands of '1' by sinking each one we find (in-place marking)."""
    islands = 0
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] == "1":
                islands += 1
                sink(g, r, c)
    return islands


def sink(g, r, c):
    if not in_bounds(g, r, c) or g[r][c] != "1":
        return
    g[r][c] = "0"
    for dr, dc in DIRS:
        sink(g, r + dr, c + dc)


