import java.util.Arrays;

public class GridRepresentation {
    static void print(String title, int[][] g) {
        System.out.println(title + " (" + g.length + "x" + g[0].length + "):");
        for (int[] row : g) System.out.println("  " + Arrays.toString(row));
    }

    public static void main(String[] args) {
        int rows = 2, cols = 3;
        int[][] g = new int[rows][cols];
        int counter = 1;
        for (int r = 0; r < rows; r++)              // row-major: rows outside,
            for (int c = 0; c < cols; c++)          // columns inside
                g[r][c] = counter++;
        print("grid", g);

        // (row, col) <-> single index
        for (int[] cell : new int[][]{{0, 2}, {1, 0}, {1, 2}}) {
            int index = cell[0] * cols + cell[1];
            System.out.println("cell (" + cell[0] + "," + cell[1] + ") -> index " + index
                    + " -> back to (" + index / cols + "," + index % cols + ")");
        }

        int[][] t = new int[cols][rows];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                t[c][r] = g[r][c];
        print("transposed", t);

        int[][] rot = new int[cols][rows];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                rot[c][rows - 1 - r] = g[r][c];
        print("rotated 90 degrees clockwise", rot);
    }
}

