DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def island_sizes(g, visited):
    """visited is None means "mark in place by turning '1' into '0'"."""
    def unvisited_land(r, c):
        return g[r][c] == "1" and (visited is None or (r, c) not in visited)

    def mark(r, c):
        if visited is not None:
            visited.add((r, c))
        else:
            g[r][c] = "0"

    sizes = []
    for r in range(len(g)):
        for c in range(len(g[0])):
            if not unvisited_land(r, c):
                continue
            size = 0
            stack = [(r, c)]
            mark(r, c)  # mark when pushed
            while stack:
                cr, cc = stack.pop()
                size += 1
                for dr, dc in DIRS:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < len(g) and 0 <= nc < len(g[0]) and unvisited_land(nr, nc):
                        mark(nr, nc)
                        stack.append((nr, nc))
            sizes.append(size)
    return sizes


